<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> format_time(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1min0s&quot;</span></span>
